import 'package:cloud_firestore/cloud_firestore.dart';class HealthStats{final double min,max,avg;final int count;const HealthStats({required this.min,required this.max,required this.avg,required this.count});}class HealthRecord{final String id;final DateTime timestamp;final double value;const HealthRecord({required this.id,required this.timestamp,required this.value});static DateTime time(DocumentSnapshot<Map<String,dynamic>> d){final v=d.data()?['timestamp'];return v is Timestamp?v.toDate():DateTime.tryParse(v?.toString()??'')??DateTime.now();}Map<String,dynamic> toFirestore()=>{'value':value,'timestamp':Timestamp.fromDate(timestamp)};}class DailyStepsModel extends HealthRecord{final int steps;const DailyStepsModel({required super.id,required super.timestamp,required this.steps}):super(value:steps.toDouble());}class SleepSessionModel extends HealthRecord{final DateTime startTime,endTime;const SleepSessionModel({required super.id,required this.startTime,required this.endTime,required super.timestamp,required super.value});}class HeartRateModel extends HealthRecord{final String? context,notes;const HeartRateModel({required super.id,required super.timestamp,required super.value,this.context,this.notes});}class WeightModel extends HealthRecord{const WeightModel({required super.id,required super.timestamp,required super.value});}class BloodSugarModel extends HealthRecord{final String type;const BloodSugarModel({required super.id,required super.timestamp,required super.value,required this.type});}class BloodPressureModel extends HealthRecord{final double diastolic;const BloodPressureModel({required super.id,required super.timestamp,required super.value,required this.diastolic});}